<template><div class="container-page py-10"><div class="flex items-center justify-between"><div><p class="text-sm text-primary-700">Admin</p><h1 class="text-3xl">Properties</h1></div><NuxtLink to="/admin/properties/new" class="btn-primary">Add Property</NuxtLink></div><p class="mt-3 text-neutral-600">Manage property records and official media.</p><div class="card mt-8 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-neutral-100"><tr><th class="p-4">Property</th><th class="p-4">Location</th><th class="p-4">From</th><th class="p-4">Status</th></tr></thead><tbody><tr v-for="property in properties" :key="property.id" class="border-t"><td class="p-4 font-semibold">{{property.name}}</td><td class="p-4">{{property.location_name}}</td><td class="p-4">{{money(property.price_from)}}</td><td class="p-4">{{property.sales_status}}</td></tr></tbody></table></div></div></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:'admin-auth'});const{list}=useProperties();const{data:properties}=useAsyncData('admin-properties',()=>list());const money=(v:number|null)=>v?new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(v):'—';useSeoMeta({title:'Manage Properties | Lexshield Admin',robots:'noindex,nofollow'})</script>
